}
public sealed class BarLayoutCard : RadioButton {
    readonly bool vertical;bool hover;
    public BarLayoutCard(string title,bool stacked){Text=title;vertical=stacked;AccessibleName=title;AccessibleDescription=stacked?"Stack the dictation controls vertically":"Arrange the dictation controls horizontally";Appearance=Appearance.Button;Size=new Size(334,174);Margin=new Padding(0,0,12,0);Cursor=Cursors.Hand;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);CheckedChanged+=(s,e)=>Invalidate();MouseEnter+=(s,e)=>{hover=true;Invalidate();};MouseLeave+=(s,e)=>{hover=false;Invalidate();};}
