    public static void PaintPreview(Graphics g,bool vertical,Rectangle area){float width=vertical?44:204,height=vertical?166:38;float scale=Math.Min(vertical?.64f:.9f,Math.Min(area.Width/width,area.Height/height));GraphicsState state=g.Save();g.TranslateTransform(area.Left+(area.Width-width*scale)/2,area.Top+(area.Height-height*scale)/2);g.ScaleTransform(scale,scale);using(GraphicsPath shape=Theme.Round(new Rectangle(0,0,(int)width,(int)height),12)){g.FillPath(Brushes.White,shape);using(Pen edge=new Pen(Theme.Line,1.5f))g.DrawPath(edge,shape);}using(Brush grip=new SolidBrush(Color.FromArgb(180,180,189)))for(int row=0;row<3;row++)for(int col=0;col<2;col++)g.FillEllipse(grip,vertical?17+row*4:9+col*4,vertical?6+col*4:14+row*4,2,2);int x=vertical?17:36,y=vertical?27:11;using(Pen mic=new Pen(Theme.Ink,1.6f)){mic.StartCap=mic.EndCap=LineCap.Round;using(GraphicsPath capsule=Theme.Round(new Rectangle(x+2,y,5,10),2))g.DrawPath(mic,capsule);g.DrawArc(mic,x-1,y+3,11,11,0,180);g.DrawLine(mic,x+4.5f,y+14,x+4.5f,y+17);g.DrawLine(mic,x+1,y+17,x+8,y+17);}if(!vertical)using(Font font=new Font("Segoe UI",9,FontStyle.Bold))g.DrawString("Dictate",font,Brushes.Black,new RectangleF(54,10,60,24));int copyX=vertical?14:122,copyY=vertical?63:11;using(Pen pen=new Pen(Theme.Ink,1.5f)){g.DrawRectangle(pen,copyX,copyY,10,11);g.FillRectangle(Brushes.White,copyX+4,copyY+4,10,11);g.DrawRectangle(pen,copyX+4,copyY+4,10,11);}if(Brand.Logo!=null)g.DrawImage(Brand.Logo,new Rectangle(vertical?11:149,vertical?96:8,22,22));using(Font font=new Font("Segoe UI",10))using(Brush ink=new SolidBrush(Theme.Muted))using(StringFormat centered=new StringFormat {Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center})g.DrawString("×",font,ink,new RectangleF(vertical?10:176,vertical?129:5,24,28),centered);g.Restore(state);}
}
